package com.myaaptha.domain.circle;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.security.Principal;
import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController @RequestMapping("/api/network/circles/{circleId}/activities") @Transactional
public class CommunityActivityController {
 public record Create(@NotBlank String kind,@NotBlank @Size(max=200) String title,@Size(max=2000) String details,@Size(max=300) String location,Instant startsAt,Instant endsAt,Boolean multiple,@Size(max=12) List<@NotBlank @Size(max=150) String> options){}
 public record Vote(@NotNull @Size(max=12) List<@NotNull @Positive Long> optionIds){}
 public record RSVP(@NotBlank String response){}
 public record Option(long id,String label,long count,boolean selected){}
 public record Activity(long id,String kind,String title,String details,String location,Instant startsAt,Instant endsAt,boolean multiple,boolean closed,boolean canManage,List<Option> options,Map<String,Long> responses,String myResponse){}
 public record Page(List<Activity> items,boolean hasNext,Long nextBefore){}
 private final JdbcTemplate db;private final CircleRepository circles;
 public CommunityActivityController(JdbcTemplate db,CircleRepository circles){this.db=db;this.circles=circles;}
 private long user(Principal p){return Long.parseLong(p.getName());}
 private com.myaaptha.domain.circle.model.CircleEntity circle(long user,long id){var c=circles.findById(id).orElseThrow(()->error(HttpStatus.NOT_FOUND,"Circle not found"));if(!c.getMemberUserIds().contains(user))throw error(HttpStatus.FORBIDDEN,"Only circle members can view activities");return c;}
 private ResponseStatusException error(HttpStatus status,String message){return new ResponseStatusException(status,message);}
 private Map<String,Object> row(long user,long circle,long activity){circle(user,circle);var rows=db.queryForList("SELECT * FROM community_activities WHERE id=? AND circle_id=? FOR UPDATE",activity,circle);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"Activity not found");return rows.getFirst();}
 private Activity dto(long user,Map<String,Object> row){long id=((Number)row.get("id")).longValue(),circle=((Number)row.get("circle_id")).longValue();var options=db.query("SELECT o.id,o.label,(SELECT COUNT(*) FROM community_poll_votes v WHERE v.option_id=o.id),CASE WHEN EXISTS(SELECT 1 FROM community_poll_votes v WHERE v.option_id=o.id AND v.user_id=?) THEN TRUE ELSE FALSE END FROM community_poll_options o WHERE o.activity_id=? ORDER BY o.id",(rs,n)->new Option(rs.getLong(1),rs.getString(2),rs.getLong(3),rs.getBoolean(4)),user,id);var responses=new LinkedHashMap<String,Long>();db.query("SELECT response,COUNT(*) FROM community_event_rsvps WHERE activity_id=? GROUP BY response",rs->{responses.put(rs.getString(1),rs.getLong(2));},id);var mine=db.queryForList("SELECT response FROM community_event_rsvps WHERE activity_id=? AND user_id=?",String.class,id,user);return new Activity(id,(String)row.get("kind"),(String)row.get("title"),(String)row.get("details"),(String)row.get("location"),instant(row.get("starts_at")),instant(row.get("ends_at")),(Boolean)row.get("multiple"),(Boolean)row.get("closed"),((Number)row.get("author_user_id")).longValue()==user||circle(user,circle).getAdminUserIds().contains(user),options,responses,mine.isEmpty()?null:mine.getFirst());}
 private Instant instant(Object value){return value==null?null:value instanceof java.time.OffsetDateTime t?t.toInstant():((java.sql.Timestamp)value).toInstant();}
 @GetMapping public Page list(Principal p,@PathVariable long circleId,@RequestParam(defaultValue="9223372036854775807") long before){long u=user(p);circle(u,circleId);var rows=db.queryForList("SELECT * FROM community_activities WHERE circle_id=? AND id<? ORDER BY id DESC LIMIT 21",circleId,before);boolean more=rows.size()>20;var page=rows.stream().limit(20).toList();return new Page(page.stream().map(r->dto(u,r)).toList(),more,page.isEmpty()?null:((Number)page.getLast().get("id")).longValue());}
 @PostMapping public Activity create(Principal p,@PathVariable long circleId,@Valid @RequestBody Create request){long u=user(p);var c=circle(u,circleId);if("ADMINS_ONLY".equals(c.getPostingPermission())&&!c.getAdminUserIds().contains(u))throw error(HttpStatus.FORBIDDEN,"Only circle admins can create activities");if(!Set.of("POLL","EVENT").contains(request.kind()))throw error(HttpStatus.BAD_REQUEST,"Choose poll or event");var options=request.options()==null?List.<String>of():request.options().stream().map(String::trim).toList();if(request.kind().equals("POLL")&&(options.size()<2||new HashSet<>(options.stream().map(v->v.toLowerCase(Locale.ROOT)).toList()).size()!=options.size()))throw error(HttpStatus.BAD_REQUEST,"Choose 2 to 12 distinct poll options");if(request.kind().equals("EVENT")&&(request.startsAt()==null||!request.startsAt().isAfter(Instant.now())||request.endsAt()!=null&&!request.endsAt().isAfter(request.startsAt())))throw error(HttpStatus.BAD_REQUEST,"Choose a future start and a later end time");var key=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(connection->{var s=connection.prepareStatement("INSERT INTO community_activities(circle_id,author_user_id,kind,title,details,location,starts_at,ends_at,multiple) VALUES(?,?,?,?,?,?,?,?,?)",new String[]{"id"});s.setLong(1,circleId);s.setLong(2,u);s.setString(3,request.kind());s.setString(4,request.title().trim());s.setString(5,Objects.requireNonNullElse(request.details(),"").trim());s.setString(6,Objects.requireNonNullElse(request.location(),"").trim());s.setTimestamp(7,request.startsAt()==null?null:java.sql.Timestamp.from(request.startsAt()));s.setTimestamp(8,request.endsAt()==null?null:java.sql.Timestamp.from(request.endsAt()));s.setBoolean(9,Boolean.TRUE.equals(request.multiple()));return s;},key);long id=Objects.requireNonNull(key.getKey()).longValue();if(request.kind().equals("POLL"))for(String option:options)db.update("INSERT INTO community_poll_options(activity_id,label) VALUES(?,?)",id,option);return dto(u,row(u,circleId,id));}
 @PostMapping("/{activityId}/vote") public Activity vote(Principal p,@PathVariable long circleId,@PathVariable long activityId,@Valid @RequestBody Vote request){long u=user(p);var row=row(u,circleId,activityId);if(!row.get("kind").equals("POLL")||Boolean.TRUE.equals(row.get("closed")))throw error(HttpStatus.CONFLICT,"This poll is closed");var ids=new HashSet<>(request.optionIds());if(!Boolean.TRUE.equals(row.get("multiple"))&&ids.size()>1)throw error(HttpStatus.BAD_REQUEST,"Choose one option");var valid=new HashSet<>(db.queryForList("SELECT id FROM community_poll_options WHERE activity_id=?",Long.class,activityId));if(!valid.containsAll(ids))throw error(HttpStatus.BAD_REQUEST,"Choose options from this poll");db.update("DELETE FROM community_poll_votes WHERE activity_id=? AND user_id=?",activityId,u);for(long id:ids)db.update("INSERT INTO community_poll_votes(activity_id,option_id,user_id) VALUES(?,?,?)",activityId,id,u);return dto(u,row);}
 @PostMapping("/{activityId}/rsvp") public Activity rsvp(Principal p,@PathVariable long circleId,@PathVariable long activityId,@Valid @RequestBody RSVP request){long u=user(p);var row=row(u,circleId,activityId);if(!row.get("kind").equals("EVENT")||Boolean.TRUE.equals(row.get("closed")))throw error(HttpStatus.CONFLICT,"This event is closed");if(!Set.of("YES","NO","MAYBE").contains(request.response()))throw error(HttpStatus.BAD_REQUEST,"Choose going, maybe or not going");db.update("DELETE FROM community_event_rsvps WHERE activity_id=? AND user_id=?",activityId,u);db.update("INSERT INTO community_event_rsvps(activity_id,user_id,response) VALUES(?,?,?)",activityId,u,request.response());return dto(u,row);}
 @PostMapping("/{activityId}/close") public Activity close(Principal p,@PathVariable long circleId,@PathVariable long activityId){long u=user(p);var r=row(u,circleId,activityId);if(!dto(u,r).canManage())throw error(HttpStatus.FORBIDDEN,"Only the creator or circle admins can close this activity");db.update("UPDATE community_activities SET closed=TRUE WHERE id=?",activityId);return dto(u,row(u,circleId,activityId));}
 @DeleteMapping("/{activityId}") public void delete(Principal p,@PathVariable long circleId,@PathVariable long activityId){long u=user(p);if(!dto(u,row(u,circleId,activityId)).canManage())throw error(HttpStatus.FORBIDDEN,"Only the creator or circle admins can remove this activity");db.update("DELETE FROM community_activities WHERE id=?",activityId);}
}
